class Person {
  *generateNames() {
    yield "Amy";
    yield "Bob";
    yield "Candy";
  }
}

let person = new Person();
let iterator = person.generateNames();

for (let name of iterator) {
  console.log(name); // Amy
                     // Bob
                     // Candy
}

class Stack {
  constructor(...items) {
    this.items = [...items];
  }

  push(value) {
    this.items.push(value);
  }
  pop() {
    return this.items.pop();
  }
  *[Symbol.iterator]() {
    yield* this.items.values();
  }
}
